  VALUES 
    (36::BIGINT, 'Muy buen profe, explica muy bien, pasa mucha gente a la pizarra y lo prepara muy bien para el examen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '95c64fb6589c41736e44a413a3960b1f5ed25903fc8d28366f2b48c666233a48'::TEXT, ARRAY[605, 563]::BIGINT[]),
    (36::BIGINT, 'Es muy buen profesor, me gusta su método de enseñanza. Vacila mucho en clase por lo que hace que la clase no sea pesada, es muy amable y si usted no entendió le vuelve a explicar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2024-04-12T00:00:00+00:00'::TIMESTAMPTZ, 'b7ef11d4747b346f02ac37325a1cf41293592f7f65c8a5fe3fd5efbcf6123fa4'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Randy = Salud Mental en la catedra'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-07-26T00:00:00+00:00'::TIMESTAMPTZ, '8823de2028be895c5054ff4ba156b8a96b673b71a5827b7f8473073019544b0e'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (36::BIGINT, 'Excelente de profesor :D'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b6793040906a8cbc31d1b09a997df6b144fa161cc690a77a9271bc187cf2381f'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (36::BIGINT, 'Excelente profesor . Lo recomiendo para todos los estudiantes del Tecnológico. Le entendí muy bien en clase y además pasé el curso con una nota de 95'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4161d5110056138ac1269f46a997f0581db90f9b24187543d5b364f8f3a61e1d'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (36::BIGINT, 'EL MEJOR PROFE DEL TEC . Todas las clases explica la materia de manera completa , con distintos ejercicios . Es graciosa la clase y se entiende a la perfeccion. Es un 100% de profesor , todo lo explica de una manera muy sencilla y facil Literal es el unico profe que me he sacado notas altas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c13e4952d1c8a8b9b98d51ac9a3655f97823014a19be668f94624818e958b389'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (36::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6de87f6c89261354dcb93739ce0413a9c1cfe355d1432d21a0b0d2e1e97cafa5'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2023-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'e91313ff494b775326f79e38c2fb733003b6bb11b6f48fa6537bbed5df75fb0f'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'El profe es bueno , da excelentes clases . Las tareas son fáciles ya que lo que explica lo deja como una evaluación. El problema es que entrega trabajos muy tardes , y uno no sabe que nota se sacó . Creo que algunas notas se las inventó ya que dejó todo al final .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-02-07T00:00:00+00:00'::TIMESTAMPTZ, '9f9b64cbfe3bdee9d7774e25a834d72c366dcb240b1e22feb6107bf61c40372d'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (36::BIGINT, 'Explica bien, pero no revisa trabajos hasta el final. Hay que rogarle para que vea los mensajes privados y no da retroalimentación de los trabajos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '9401abdda34861c56fad6bad2ff6272205f3eb13d38cdd74c91a7e967d3d8968'::TEXT, ARRAY[605]::BIGINT[]),
    (36::BIGINT, 'El profe explica muy bien, es bastante amable y si necesita volverle a explicar no tienen ningún problema, es muy respetuoso y agradable. Sin embargo, a veces se pasa con la dificultad de los trabajos y/o la cantidad de ejercicios. Por último, es muy muy irresponsable con la entrega de notas.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, '7c1b5258a3ffbc8cefcb427243362b9eca8cd44b0ae7f1aabce1183bf4e1b9e7'::TEXT, ARRAY[605]::BIGINT[]),
    (36::BIGINT, 'No recomendado para Proba de Compu'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2022-09-16T00:00:00+00:00'::TIMESTAMPTZ, '21fb9754bf88daf96dc992165baeb009efd0ebb0869c615ae7aa1f71514b94e1'::TEXT, ARRAY[1049]::BIGINT[]),
    (36::BIGINT, 'Muy buen profesor en todos los sentidos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-08-04T00:00:00+00:00'::TIMESTAMPTZ, '145bcc5b67387a36271ddbff3c66b6d2af3d5c0b2db9e9d6482f4a381f211d6c'::TEXT, ARRAY[634]::BIGINT[]),
    (36::BIGINT, 'El profesor es muy bueno explicando. Puedes preguntarle sin problema cuando tengas alguna duda y siempre está anuente a explicar. Antes de los exámenes hace sesiones de resolución de ejercicios.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'de314e14cfde927e0e088cf291557d5d51605c2c555033e9e450d2d599d67df5'::TEXT, ARRAY[605]::BIGINT[]),
    (36::BIGINT, 'No matricular con este profe!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2022-05-16T00:00:00+00:00'::TIMESTAMPTZ, 'fb79f4c3d2310edec852504755811625f38f523952db786dc83b666032f745ff'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Transmite la materia de forma muy clara, y como persona es maravillosa. Sin embargo es bastante irresponsable entregando notas, pocas tareas, y a veces cuesta que de consultas aún pidiéndole con anticipó. Las últimas semanas del semestre si sentí que aflojo mucho la calidad de las clases.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2021-12-14T00:00:00+00:00'::TIMESTAMPTZ, '3e1a356bbce5ad977c71efe65cf7128fda30cc88501d6baa184e65708b31902d'::TEXT, ARRAY[923]::BIGINT[]),
    (36::BIGINT, 'El profe orienta muy bien durante las clases. A veces el que el curso sea muy temprano pasa la factura porque al palmarla por otros cursos cuesta despertarse para recibirla. Los quices son bastantes fáciles, con solo seguir los videos de él se hacen muy bien. No califica duro y es muy accesible.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '7eb3fa9e2b5869c12119c8d21949906faf5e54c2ce816dc99bcddd9d8d3486ac'::TEXT, ARRAY[923]::BIGINT[]),
    (36::BIGINT, 'En un contexto virtual, a él no le gusta dar muchas clases a lo largo del semestre, deja quices sin siquiera haber visto la materia para aplicarlos. Da poca retroalimentación y no es muy ágil para responder correos o dudas de los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra']::TEXT[], '2021-11-08T00:00:00+00:00'::TIMESTAMPTZ, '9aeddf3dfb4927dbe4ca2984179b6ce678265c3db295bdb4757078f5e1866b1f'::TEXT, ARRAY[923]::BIGINT[]),
    (36::BIGINT, 'El profesor explica muy bien y antes de los exámenes se hacen ejercicios de repaso y aclaración de ejercicios de las prácticas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'd6f79b6e7c2b3a64ea6e715276805bc9e4c51a5db2e2ced87f4200f9af49cc56'::TEXT, ARRAY[634]::BIGINT[]),
    (36::BIGINT, 'El profesor es muy bueno en lo que hace. Procura siempre preguntar si vamos o no entendiendo la materia. Se preocupa mucho por que vayamos al día. Lo recomiendo mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '41ccfc27f188fc210ff52dc91495591324075e13b67eaf3b16d034daad5e161e'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Explica relativamente bien, siempre tarde, en general no lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '59b2ae14d048f8475f278a25d75ad2b9c6f52f2619e81614bd5d16966aac56b5'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Excelente profe, sabe explicar de una forma fácil y bastante clara. Si alguien no comprende algo él lo explica hasta entenderlo. La verdad me gustaron mucho clases clase con él. Sí lo recomiendo. Solo que es un poco impuntual y las tareas las entrega hasta final de semestre y uno no sabe como va.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '5e8c9387ab61a8bbf331c8abfb1b3fa2781a15930b15341048c8a0d93b38b953'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Es un excelente profesor. Explica muy bien. Es muy empático. Algunos compañeros en ocasiones se quieren abusar de su empatía inventando excusas cuando no presentan sus tareas a tiempo. Se le puede preguntar en clase varias veces y él te ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'c574e9f3736b79cd5814ca673d335daf7aeb8e3ff8fcaabc10b2f99be1b74b7e'::TEXT, ARRAY[1049]::BIGINT[]),
    (36::BIGINT, 'Nunca da retroalimentación de las tareas, hasta semana 18 se sabe como va en el semestre, antes nunca da notas de nada, no se embarquen, NO LO RECOMIENDO.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'Pocos exámenes']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '88749556338af33381410efa35793ee12fb069d4f98aa5c1a99818906f91f3fe'::TEXT, ARRAY[1049]::BIGINT[]),
    (36::BIGINT, 'Explica demasiado bien. He llevado el curso no se ya cuantas veces y ahora que es virtual aproveché para matricular en Limón y ha sido de lo mejor. ¡Excelente profesor! Te aclara todas las dudas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-10-07T00:00:00+00:00'::TIMESTAMPTZ, '5031db4c6db0ed45e09cdb59299b0e6cc8c360eb03dcb08e0cd07cbc68317e3d'::TEXT, ARRAY[1018]::BIGINT[]),
    (36::BIGINT, 'Siempre llega tarde, a veces hasta 30 minutos tarde. No cubre todos los temas del examen, se atrasa un montón con la materia. Durante las clases vacila mucho y se pierde tiempo. Cero vocación para impartir las clases. La experiencia realmente fue pésima. No lo recomiendo para nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '609a01c34182ff066cbc5cbde40b31df344e137dfb5f0f7d52feb6054f978140'::TEXT, ARRAY[634]::BIGINT[]),
    (36::BIGINT, 'Enseña muy bien, pero a como enseña se espera que usted lo haya aprendido bien. De actitud es muy carismático y cómico.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'b5bd0eab68ef39554d4ca49bb860be606127c5d7c13c21d6d789d6bcf0a17d00'::TEXT, ARRAY[2439]::BIGINT[]),
    (36::BIGINT, 'Es muy buen profesor, soy primer ingreso y realmente es increíble ver a alguien que haga cálculos tan amplios ver de una manera más simple.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2020-03-12T00:00:00+00:00'::TIMESTAMPTZ, '6dac960598ab2ccf50da9406f966953e1d05678a4bae0516e73bc6e41292e481'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'No explica correctamente, llega tarde, antes hacia quices en la pizarra y calificarlos enfrente toda la clase.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, '0457b08226b370ef9ef125a2efc33a107276b82670fdd59c4c9896995e4906ba'::TEXT, ARRAY[2439]::BIGINT[]),
    (36::BIGINT, 'Excelente profe, pero califica duró.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'd495e7f1e364c2951dc2ae9bad2347db3d97e4811a1caf44f0691b9e4d1a3c93'::TEXT, ARRAY[1018]::BIGINT[]),
    (36::BIGINT, 'siempre llega tarde y pierde tiempo en sus lecciones.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-10-13T00:00:00+00:00'::TIMESTAMPTZ, 'e33bec7732993ac1ee98a6329932df8923d1f80197803a4ecf36271a825fe9d4'::TEXT, ARRAY[935]::BIGINT[]),
    (36::BIGINT, 'Muy buen profesor, solo que no deja muchas tareas por ende tienen que ser constantes con la materia en temas de prácticas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'bdd887711bf4b1a258e9d1ae5a3f158231ffc4ea9048280af5586a17e99bb429'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c91f51115394c3fbc7d3ed574933bc93431d18084fb9fa81d66147f6cead475a'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'El profe es muy buena nota y explica bien, pero a la hora de los examenes es muy duro, tiene que estudiar bastante, y si vas a matricular este curso preparate en hacer bastantes preguntas y estudiar mucho, porque el verá el interés del estudiante.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Respetado por los estudiantes']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '50d5a2db78f3e9d5476d906c85e4b78223931feaea9be09e335ee29c360c46d2'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1df699d5485aa11c162295e83c9cf782777a900d8043c1bf3f590f9027da252f'::TEXT, ARRAY[2444]::BIGINT[]),
    (36::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8868b0e1ec7c73ce7cb4500206a86465f6d0d5bee9e78cac0fbdfd3cedf7d8ee'::TEXT, ARRAY[563]::BIGINT[]),
    (36::BIGINT, 'Es un excelente profesor!!!! Excelente Wynta!!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-04-09T00:00:00+00:00'::TIMESTAMPTZ, '02dd6f4e770695ec1f0f0a3e4c032aec4ff108b87bd215950ee60dc9ced9ca8e'::TEXT, ARRAY[1018, 634]::BIGINT[]),
    (36::BIGINT, 'Explica muy bien, los ejemplos que da son claros. Es como todo curso se debe practicar bastante y lo pasarás sin problemas. Si muestras una actitud positiva hacia el curso, el siempre estará dispuesto a aclararte las dudas en cualquier momento. Y Como persona es muy pura vida.!!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2015-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'a42a82816c97ae742bd12d546d5224478eacc128e3a5b31cd6ccbaeb07a7b9f0'::TEXT, ARRAY[1018]::BIGINT[]),
    (36::BIGINT, 'Profesor excelente, de los mejor del TEC.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'a0db666bc1693b7acee41fdbb24c711c8a6ee6f1b40fd523fdb58f26cfb25fee'::TEXT, ARRAY[1018]::BIGINT[]),
    (36::BIGINT, 'Un profe bueno para explicar y atiende las dudas siempre y cuando uno sea responsable.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-14T00:00:00+00:00'::TIMESTAMPTZ, 'c1c9f04127b035fcb6548fd09bea229994f2507bade452d2f46a8847dab00535'::TEXT, ARRAY[605]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
